package com.xuyuan.blog.admin.service.impl;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.baomidou.mybatisplus.core.metadata.IPage;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.xuyuan.blog.admin.dto.*;import com.xuyuan.blog.admin.mapper.ScheduleMapper;import com.xuyuan.blog.admin.service.AdminScheduleService;import com.xuyuan.blog.admin.vo.schedule.AdminScheduleVO;import com.xuyuan.blog.common.result.*;import com.xuyuan.blog.model.entity.Schedule;import lombok.RequiredArgsConstructor;import org.springframework.beans.BeanUtils;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class AdminScheduleServiceImpl implements AdminScheduleService {private final ScheduleMapper mapper;public PageResult<AdminScheduleVO> pageList(ScheduleQueryParam p){IPage<AdminScheduleVO> r=mapper.pageAdminList(new Page<>(Math.max(1,p.getPage()),p.getPageSize()),p);return PageResult.of(r.getRecords(),r.getTotal(),r.getCurrent(),r.getSize());}@Transactional public Long create(ScheduleCreateParam p){Schedule s=new Schedule();BeanUtils.copyProperties(p,s);mapper.insert(s);return s.getId();}@Transactional public void update(Long id,ScheduleCreateParam p){Schedule s=get(id);BeanUtils.copyProperties(p,s);mapper.updateById(s);}@Transactional public void delete(Long id){mapper.deleteById(get(id).getId());}private Schedule get(Long id){Schedule s=mapper.selectById(id);if(s==null)throw ResultCode.PARAM_ERROR.toException("日程不存在");return s;}}
